<script setup lang="ts">
import { ref, reactive, watch } from 'vue'
import { Plus, Refresh } from '@element-plus/icons-vue'
import { api, post, items, query, errorText } from '../api'
import { useLoad, today } from '../composables'
import { useAuth } from '../stores/auth'
import { ElMessage, ElMessageBox } from 'element-plus'
import StatusTag from '../components/StatusTag.vue'
const auth=useAuth(),tab=ref<'leave'|'correction'>('leave'),rows=ref<any[]>([]),page=ref(1),total=ref(0),status=ref(''),dialog=ref(false),saving=ref(false),formError=ref(''),reviewOpen=ref(false),reviewRow=ref<any>(null),approved=ref(true),comment=ref('')
const form=reactive({range:[] as string[],type:'PERSONAL',reason:'',date:'',requestedTime:'09:00',punchType:'IN'})
const leaveTypes:Record<string,string>={PERSONAL:'事假',SICK:'病假',ANNUAL:'年假',OTHER:'其他'}
const path=()=>`/${tab.value}-requests`
const {loading,error,load}=useLoad(async()=>{const data=await api(path()+'?'+query({page:page.value-1,size:20,status:status.value}));rows.value=items(data);total.value=data.total??rows.value.length})
watch(tab,()=>{page.value=1;status.value='';load()})
function newRequest(){Object.assign(form,{range:[],type:'PERSONAL',reason:'',date:'',requestedTime:'09:00',punchType:'IN'});formError.value='';dialog.value=true}
function disabledDate(date:Date){const value=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(date);const lower=new Date(`${today()}T00:00:00+08:00`);lower.setUTCDate(lower.getUTCDate()-7);const first=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).format(lower);return value>=today()||value<first}
async function submit(){if(!form.reason.trim()){formError.value='请填写申请原因';return}if(tab.value==='leave'&&form.range.length!==2){formError.value='请选择完整的请假日期区间';return}if(tab.value==='correction'&&(!form.date||!form.requestedTime)){formError.value='请选择补卡日期和时间';return}saving.value=true;formError.value='';try{await post(path(),tab.value==='leave'?{startDate:form.range[0],endDate:form.range[1],type:form.type,reason:form.reason.trim()}:{date:form.date,type:form.punchType,requestedTime:form.requestedTime,reason:form.reason.trim()});ElMessage.success('申请已提交');dialog.value=false;page.value=1;load()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
async function cancel(row:any){try{await ElMessageBox.confirm('撤销后如需继续办理，需要重新提交申请。','撤销申请',{confirmButtonText:'撤销申请',cancelButtonText:'保留申请'});await post(`${path()}/${row.id}/cancel`);ElMessage.success('申请已撤销');load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(errorText(e))}}
function review(row:any,value:boolean){reviewRow.value=row;approved.value=value;comment.value='';formError.value='';reviewOpen.value=true}
async function submitReview(){if(!approved.value&&!comment.value.trim()){formError.value='请填写驳回原因，方便申请人了解处理结果';return}saving.value=true;formError.value='';try{await post(`${path()}/${reviewRow.value.id}/review`,{approved:approved.value,comment:comment.value.trim()});reviewOpen.value=false;ElMessage.success(approved.value?'申请已批准':'申请已驳回');load()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
function own(row:any){return row.employeeId===auth.user?.employeeId||row.userId===auth.user?.id}
</script>
<template><div class="page-head"><div><h1>{{auth.isAdmin?'申请与审批':'请假与补卡'}}</h1></div><el-button type="primary" :icon="Plus" :disabled="!auth.user?.employeeId" @click="newRequest">{{tab==='leave'?'申请请假':'申请补卡'}}</el-button></div><el-alert v-if="!auth.user?.employeeId" title="当前账号可处理审批。提交个人申请需先关联员工档案。" type="info" :closable="false"/><div class="panel"><el-tabs v-model="tab"><el-tab-pane label="请假申请" name="leave"/><el-tab-pane label="补卡申请" name="correction"/></el-tabs><div class="toolbar"><el-select v-model="status" placeholder="全部状态" clearable style="width:170px" @change="page=1;load()"><el-option label="待审批" value="PENDING"/><el-option label="已批准" value="APPROVED"/><el-option label="已驳回" value="REJECTED"/><el-option label="已撤销" value="CANCELLED"/></el-select><el-button :icon="Refresh" :loading="loading" @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-table :data="rows" v-loading="loading" empty-text="暂无申请记录"><el-table-column v-if="auth.isAdmin" prop="employeeName" label="申请人" min-width="100"/><el-table-column label="申请日期" min-width="190"><template #default="{row}">{{tab==='leave'?`${row.startDate} 至 ${row.endDate}`:row.date}}</template></el-table-column><el-table-column label="类型" width="110"><template #default="{row}">{{tab==='leave'?(leaveTypes[row.type]||row.type):row.type==='IN'?'补签到':'补签退'}}</template></el-table-column><el-table-column v-if="tab==='correction'" prop="requestedTime" label="申请时间" width="100"/><el-table-column prop="reason" label="申请原因" min-width="200" show-overflow-tooltip/><el-table-column label="状态" width="100"><template #default="{row}"><StatusTag :status="row.status" request/></template></el-table-column><el-table-column label="审批意见" min-width="150" show-overflow-tooltip><template #default="{row}">{{row.reviewComment||row.comment||'—'}}</template></el-table-column><el-table-column label="操作" min-width="145" fixed="right"><template #default="{row}"><template v-if="row.status==='PENDING'"><template v-if="auth.isAdmin&&!own(row)"><el-button text type="primary" size="small" @click="review(row,true)">批准</el-button><el-button text type="danger" size="small" @click="review(row,false)">驳回</el-button></template><el-button v-if="own(row)||!auth.isAdmin" text size="small" @click="cancel(row)">撤销申请</el-button></template><span v-else class="muted">已处理</span></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="load"/></div></div><p class="footnote">请假按整天申请；补卡限近 7 个已结束自然日中的工作日。批准后保留原始记录，管理员不能审批本人申请。</p><el-dialog v-model="dialog" :title="tab==='leave'?'新建请假申请':'新建补卡申请'" width="550px" :close-on-click-modal="false"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top"><template v-if="tab==='leave'"><el-form-item label="请假日期（整天）" required><el-date-picker v-model="form.range" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期" style="width:100%"/></el-form-item><el-form-item label="请假类型" required><el-select v-model="form.type"><el-option v-for="(label,key) in leaveTypes" :key="key" :value="key" :label="label"/></el-select></el-form-item></template><template v-else><el-form-item label="补卡日期" required><el-date-picker v-model="form.date" type="date" value-format="YYYY-MM-DD" :disabled-date="disabledDate" style="width:100%"/></el-form-item><div class="form-grid"><el-form-item label="补卡类型" required><el-select v-model="form.punchType"><el-option label="补签到" value="IN"/><el-option label="补签退" value="OUT"/></el-select></el-form-item><el-form-item label="申请时间" required><el-time-picker v-model="form.requestedTime" format="HH:mm" value-format="HH:mm" style="width:100%"/></el-form-item></div></template><el-form-item label="申请原因" required><el-input v-model="form.reason" type="textarea" :rows="4" maxlength="500" show-word-limit placeholder="请填写申请原因"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="submit">提交申请</el-button></template></el-dialog><el-dialog v-model="reviewOpen" :title="approved?'批准申请':'驳回申请'" width="480px"><p class="help-text">申请人：{{reviewRow?.employeeName}}<br>原因：{{reviewRow?.reason}}</p><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-input v-model="comment" type="textarea" :rows="4" maxlength="255" show-word-limit :placeholder="approved?'审批意见（可选）':'请说明驳回原因'"/><template #footer><el-button @click="reviewOpen=false">取消</el-button><el-button :type="approved?'primary':'danger'" :loading="saving" @click="submitReview">确认{{approved?'批准':'驳回'}}</el-button></template></el-dialog></template>
